using NUnit.Framework;

[TestFixture]
public class PrimeNumberTests
{
    [TestCase(2, true)]
    [TestCase(3, true)]
    [TestCase(4, false)]
    [TestCase(17, true)]
    [TestCase(1, false)]
    public void IsPrime_ReturnsExpected(int n, bool expected)
    {
        Assert.That(IsPrime(n), Is.EqualTo(expected));
    }

    private bool IsPrime(int n)
    {
        if (n <= 1)
            return false;

        for (int i = 2; i * i <= n; i++)
        {
            if (n % i == 0)
                return false;
        }

        return true;
    }
}
